:root {
  color-scheme: light;
  --paper: #fffdf7;
  --ink: #282c27;
  --muted: #74796e;
  --green: #3d6653;
  --mint: #e6efe7;
  --coral: #d8755c;
  --line: #e8e2d6;
}
* { box-sizing: border-box; }
[hidden] { display: none !important; }
body {
  margin: 0;
  min-height: 100vh;
  padding: 40px 18px;
  display: grid;
  place-items: start center;
  background-color: #f4efe3;
  background-image: radial-gradient(#d9d0bd 1px, transparent 1px);
  background-size: 18px 18px;
  color: var(--ink);
  font: 16px/1.5 system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
}
button, input, textarea { font: inherit; }
.board {
  width: min(100%, 620px);
  padding: 38px clamp(22px, 6vw, 48px) 24px;
  background: var(--paper);
  border: 2px solid var(--ink);
  border-radius: 10px;
  box-shadow: 8px 8px 0 var(--ink);
}
.header { margin-bottom: 28px; }
.eyebrow, footer { color: var(--green); font-size: 12px; font-weight: 800; letter-spacing: .13em; }
.eyebrow { margin: 0 0 6px; }
h1 { margin: 0; font-size: clamp(30px, 7vw, 42px); line-height: 1.1; letter-spacing: -.04em; }
h1 span { color: var(--coral); }
.intro { margin: 9px 0 0; color: var(--muted); }
.note-form { display: grid; gap: 9px; padding: 20px; background: #f7f3e9; border: 1px solid var(--line); border-radius: 8px; }
label { font-weight: 700; }
.hint { color: var(--muted); font-size: 14px; font-weight: 400; }
textarea, input {
  width: 100%; padding: 11px 12px; color: var(--ink); background: var(--paper);
  border: 1px solid #cfc8b9; border-radius: 5px; resize: vertical;
}
textarea { min-height: 76px; }
textarea:focus, input:focus, button:focus-visible { outline: 3px solid #e7a18e; outline-offset: 2px; }
button { cursor: pointer; }
.add-button {
  justify-self: start; margin-top: 4px; padding: 10px 16px; color: white; background: var(--green);
  border: 2px solid var(--green); border-radius: 5px; font-weight: 750; transition: transform .12s, background .12s;
}
.add-button:hover { background: #2e5141; }
.add-button:active { transform: translateY(2px); }
.notes-section { margin-top: 32px; }
.section-heading { display: flex; align-items: center; justify-content: space-between; gap: 12px; }
h2 { margin: 0; font-size: 20px; letter-spacing: -.02em; }
.count { display: inline-grid; min-width: 25px; height: 25px; margin-left: 4px; place-items: center; color: var(--green); background: var(--mint); border-radius: 50%; font-size: 13px; vertical-align: 2px; }
.filter-status { display: flex; align-items: center; gap: 9px; color: var(--muted); font-size: 14px; }
.filter-status strong { color: var(--green); }
.clear-button { padding: 4px 8px; color: var(--green); background: transparent; border: 1px solid #b6c8b9; border-radius: 4px; font-size: 14px; }
.clear-button:hover { background: var(--mint); }
.notes-list, .tag-list { padding: 0; margin: 12px 0 0; list-style: none; }
.notes-list { display: grid; gap: 10px; }
.note-card { padding: 15px 16px; border: 1px solid var(--line); border-left: 4px solid var(--coral); border-radius: 5px; overflow-wrap: anywhere; }
.note-text { margin: 0; white-space: pre-wrap; }
.note-tags { display: flex; flex-wrap: wrap; gap: 7px; margin-top: 12px; }
.tag-button { padding: 4px 9px; color: var(--green); background: var(--mint); border: 1px solid transparent; border-radius: 20px; font-size: 14px; }
.tag-button:hover, .tag-button[aria-pressed="true"] { background: var(--green); color: white; }
.empty-state, .no-tags { margin: 14px 0 0; color: var(--muted); }
.tag-section { margin-top: 28px; padding-top: 21px; border-top: 1px dashed #d9d1c2; }
.tag-list { display: flex; flex-wrap: wrap; gap: 8px; }
.tag-count { margin-left: 5px; opacity: .72; }
footer { margin-top: 28px; padding-top: 16px; border-top: 1px solid var(--line); font-size: 10px; text-align: center; }
@media (max-width: 420px) {
  body { padding: 20px 14px; }
  .board { padding: 28px 20px 20px; box-shadow: 5px 5px 0 var(--ink); }
  .note-form { padding: 16px; }
  .section-heading { align-items: flex-start; flex-wrap: wrap; }
  .filter-status { width: 100%; }
}

const form = document.querySelector('#note-form');
const textInput = document.querySelector('#note-text');
const tagsInput = document.querySelector('#note-tags');
const notesList = document.querySelector('#notes-list');
const tagList = document.querySelector('#tag-list');
const emptyState = document.querySelector('#empty-state');
const noTags = document.querySelector('#no-tags');
const noteTotal = document.querySelector('#note-total');
const filterStatus = document.querySelector('#filter-status');
const activeTagLabel = document.querySelector('#active-tag');
const clearFilterButton = document.querySelector('#clear-filter');

const notes = [];
let activeTag = null;

function parseTags(value) {
  return [...new Set(value.split(',').map(tag => tag.trim()).filter(Boolean))];
}

function makeTagButton(tag, count, isFilter = false) {
  const li = document.createElement('li');
  const button = document.createElement('button');
  button.type = 'button';
  button.className = 'tag-button';
  button.setAttribute('aria-pressed', String(activeTag === tag));
  button.setAttribute('aria-label', isFilter ? `Filter notes by ${tag}, ${count} notes` : `Show notes tagged ${tag}`);
  button.append(document.createTextNode(tag));
  if (!isFilter) {
    const number = document.createElement('span');
    number.className = 'tag-count';
    number.textContent = String(count);
    button.append(number);
  }
  button.addEventListener('click', () => {
    activeTag = activeTag === tag ? null : tag;
    render();
  });
  li.append(button);
  return li;
}

function render() {
  const visibleNotes = activeTag ? notes.filter(note => note.tags.includes(activeTag)) : notes;
  notesList.replaceChildren();
  for (const note of [...visibleNotes].reverse()) {
    const item = document.createElement('li');
    item.className = 'note-card';
    const content = document.createElement('p');
    content.className = 'note-text';
    content.textContent = note.text;
    item.append(content);
    if (note.tags.length) {
      const tags = document.createElement('div');
      tags.className = 'note-tags';
      for (const tag of note.tags) tags.append(makeTagButton(tag, 0, true));
      item.append(tags);
    }
    notesList.append(item);
  }
  emptyState.hidden = visibleNotes.length > 0;
  emptyState.textContent = notes.length === 0
    ? 'Your page is blank. Add a note to get started.'
    : activeTag ? `No notes tagged “${activeTag}”.` : 'No notes to show.';
  noteTotal.textContent = String(visibleNotes.length);
  filterStatus.hidden = activeTag === null;
  activeTagLabel.textContent = activeTag ?? '';

  const counts = new Map();
  for (const note of notes) for (const tag of note.tags) counts.set(tag, (counts.get(tag) || 0) + 1);
  tagList.replaceChildren();
  for (const [tag, count] of [...counts].sort(([a], [b]) => a.localeCompare(b))) {
    tagList.append(makeTagButton(tag, count));
  }
  noTags.hidden = counts.size > 0;
}

form.addEventListener('submit', event => {
  event.preventDefault();
  const text = textInput.value.trim();
  if (!text) { textInput.focus(); return; }
  notes.push({ text, tags: parseTags(tagsInput.value) });
  form.reset();
  activeTag = null;
  render();
  textInput.focus();
});

clearFilterButton.addEventListener('click', () => {
  activeTag = null;
  render();
});

render();
